update TB_WIFI_MEMBER
   set point_expire_dt = case when point_expire_dt is null or point_expire_dt < #{expireDt} then #{expireDt} else point_expire_dt end
 where id = #{id}

mapper.sql:
where m.status != 'DELETED'

    and m.tel like concat('%', #{keyword}, '%')


    and m.status = #{status}

mapper.select:
select d.*, m.tel as member_tel
  from TB_WIFI_DEVICE d left join TB_WIFI_MEMBER m on m.id = d.member_id
 where d.sn = #{sn}

