update TB_WIFI_DEVICE set member_id = null, registered_dt = null, modify_dt = now()
 where sn = #{sn}
 and member_id = #{memberId}

update TB_WIFI_PRODUCT set tuge_active = 'N', sale_yn = 'N'
 where tuge_active = 'Y' and product_code not in
#{c}

update TB_WIFI_CATEGORY
   set parent_id = #{parentId}, name = #{name}, image = #{image}, sort = #{sort}, use_yn = #{useYn},
       usd_rate = #{usdRate}, margin_rate = #{marginRate}, period_rules = #{periodRules}
 where id = #{id}
